func.func @main(%arg0: tensor<6xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x6x7x7xf32>) -> tensor<6x6x7x7xf32> {
  %c0_i64 = stablehlo.constant 0 : tensor<i64>
  %c1_i64 = stablehlo.constant 1 : tensor<i64>
  %c0_f32 = stablehlo.constant 0.000000e+00 : tensor<f32>
  %c1_f32 = stablehlo.constant 1.000000e+00 : tensor<f32>
  %eps = stablehlo.constant 1.000000e-05 : tensor<f32>

  // Compute mean over batch and spatial dimensions (0, 2, 3)
  %reduce_sum = "stablehlo.reduce"(%arg2, %c0_f32) ({
    ^bb0(%lhs: tensor<f32>, %rhs: tensor<f32>):
      %sum = stablehlo.add %lhs, %rhs : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6xf32>

  %count = stablehlo.constant 294.000000e+00 : tensor<f32>  // 6 * 7 * 7
  %mean = stablehlo.divide %reduce_sum, %count : tensor<6xf32>

  // Compute variance: E[(x - mean)^2]
  // First broadcast mean to full shape
