func.func @main(%x: tensor<4x5xf32>, %y: tensor<2x5xf32>) -> tensor<4x2xf32> {
  // Broadcast x to shape 4x2x5 (each row of x is replicated 2 times)
  %x_broadcasted = "stablehlo.broadcast_in_dim"(%x) {broadcast_dimensions = array<i64: 0, 2>} : (tensor<4x5xf32>) -> tensor<4x2x5xf32>

  // Broadcast y to shape 4x2x5 (each row of y is replicated 4 times)
  %y_broadcasted = "stablehlo.broadcast_in_dim"(%y) {broadcast_dimensions = array<i64: 1, 2>} : (tensor<2x5xf32>) -> tensor<4x2x5xf32>

  // Compute element-wise difference: (x[i, d] - y[j, d])
  %diff = stablehlo.subtract %x_broadcasted, %y_broadcasted : tensor<4x2x5xf32>

  // Square the differences element-wise: (x[i, d] - y[j, d])^2
  %squared_diff = stablehlo.multiply %diff, %diff : tensor<4x2x5xf32>

  // Reduce along the last dimension (d) with sum to get the final result
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %result = "stablehlo.reduce"(%squared_diff, %zero) ({
    ^bb0(%arg0: tensor<f32>, %arg1: tensor<f32>):
      %sum = stablehlo.add %arg0, %arg1 : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<4x2x5xf32>, tensor<f32>) -> tensor<4x2xf32>

  return %result : tensor<4x2xf32>
}

func.func @main(%x: tensor<4x5xf32>, %y: tensor<2x5xf32>) -> tensor<4x2xf32> {
  // Broadcast x from [4,5] to [4,2,5] 
  // Dimensions [0,2] mean we keep original dims 0 and 1 of x at positions 0 and 2 in result
  %x_broadcast = "stablehlo.broadcast_in_dim"(%x) {broadcast_dimensions = array<i64: 0, 2>} : (tensor<4x5xf32>) -> tensor<4x2x5xf32>

