  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %result = "stablehlo.reduce"(%squared_diff, %zero) ({
  ^bb0(%arg0: tensor<f32>, %arg1: tensor<f32>):
    %sum = "stablehlo.add"(%arg0, %arg1) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<4x2x5xf32>, tensor<f32>) -> tensor<4x2xf32>

  return %result : tensor<4x2xf32>
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
