  // Compute mean and variance across batch dimension (dimension 0)
  %zero_f32 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %one_f32 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %batch_size = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>

