  %diff = "stablehlo.subtract"(%linear_result, %mean_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %diff_squared = "stablehlo.multiply"(%diff, %diff) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  %variance_sum = "stablehlo.reduce"(%diff_squared, %zero_f32) ({ 
  ^bb0(%arg5: tensor<f32>, %arg6: tensor<f32>): 
    %sum = "stablehlo.add"(%arg5, %arg6) : (tensor<f32>, tensor<f32>) -> tensor<f32>
    "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  %variance = "stablehlo.divide"(%variance_sum, %batch_size) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>

