  %epsilon = "stablehlo.constant"() {value = dense<1.0E-5> : tensor<f32>} : () -> tensor<f32>
  %variance_eps = "stablehlo.add"(%variance, %epsilon) : (tensor<7xf32>, tensor<f32>) -> tensor<7xf32>

