  %sqrt_two_broadcast = "stablehlo.broadcast_in_dim"(%sqrt_two) {broadcast_dimensions = array<i64: 1>} : (tensor<f32>) -> tensor<6x7xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one_f32_2) {broadcast_dimensions = array<i64: 1>} : (tensor<f32>) -> tensor<6x7xf32>

  %x_div_sqrt2 = "stablehlo.divide"(%batch_norm_result, %sqrt_two_broadcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %erf_val = "chlo.erf"(%x_div_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %one_plus_erf = "stablehlo.add"(%one_broadcast, %erf_val) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  %gelu_result = "stablehlo.multiply"(%batch_norm_result, %one_plus_erf) : (tensor<6x7xf32>, tensor<6x7xf32>)

