func.func @main(%arg0: tensor<7x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  %cst = stablehlo.constant dense<1.0> : tensor<f32>
  %cst_0 = stablehlo.constant dense<0.0> : tensor<f32>
  %cst_1 = stablehlo.constant dense<-1.0> : tensor<f32>
  %cst_2 = stablehlo.constant dense<0.5> : tensor<f32>
  %cst_3 = stablehlo.constant dense<2.0> : tensor<f32>
  %cst_4 = stablehlo.constant dense<1.0> : tensor<6x7x12x12xf32>
  %cst_5 = stablehlo.constant dense<-1.0> : tensor<6x7x12x12xf32>
  %cst_6 = stablehlo.constant dense<1.0> : tensor<6x7x12x12xf32>

  // Transposed convolution: conv_transpose(x)
  // For ConvTranspose2d(in_channels=7, out_channels=7, kernel_size=3, stride=2, padding=1, output_padding=1)
  // This maps to convolution with lhs_dilation=stride=2, rhs_dilation=1, padding calculated appropriately
  // Output size calculation: (input - 1) * stride - 2 * padding + kernel + output_padding = 
  // (6-1)*2 - 2*1 + 3 + 1 = 5*2 - 2 + 4 = 12
  %0 = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>, 
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[i, o, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Add bias: need to broadcast bias from tensor<7xf32> to tensor<6x7x12x12xf32>
  %1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x12x12xf32>
  %2 = stablehlo.add %0, %1 : tensor<6x7x12x12xf32>

  // Mish activation: x * tanh(softplus(x)) where softplus = log(1 + exp(x))
  // First compute softplus = log(1 + exp(x))
  %3 = stablehlo.exponential %2 : tensor<6x7x12x12xf32>
  %4 = stablehlo.add %3, %cst_4 : tensor<6x7x12x12xf32>
  %5 = stablehlo.log %4 : tensor<6x7x12x12xf32>

  // Then compute tanh(softplus)
  %6 = stablehlo.tanh %5 : tensor<6x7x12x12xf32>

  // Finally multiply: x * tanh(softplus)
  %7 = stablehlo.multiply %2, %6 : tensor<6x7x12x12xf32>

  // Add value: x + self.add_value (add_value = 0.5)
  %8 = stablehlo.add %7, %cst_2 : tensor<6x7x12x12xf32>

  // Hardtanh: clamp between -1 and 1
  // max(-1, min(1, x))
  %9 = stablehlo.minimum %8, %cst_6 : tensor<6x7x12x12xf32>
  %10 = stablehlo.maximum %9, %cst_5 : tensor<6x7x12x12xf32>

  // Scale: x * self.scale (scale = 2.0)
  %11 = stablehlo.multiply %10, %cst_3 : tensor<6x7x12x12xf32>

