func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  %cst = stablehlo.constant dense<12.0> : tensor<f32>
  %cst_0 = stablehlo.constant dense<0.0> : tensor<f32>

  // Compute log(predictions) and log(targets)
  %0 = stablehlo.log %arg0 : tensor<12x12xf32>
  %1 = stablehlo.log %arg1 : tensor<12x12xf32>

  // Compute log(targets) - log(predictions)
  %2 = stablehlo.subtract %1, %0 : tensor<12x12xf32>

  // Compute targets * (log(targets) - log(predictions))
  %3 = stablehlo.multiply %arg1, %2 : tensor<12x12xf32>

  // Sum all elements to get the total KL divergence
  %4 = "stablehlo.reduce"(%3, %cst_0) ({
  ^bb0(%arg2: tensor<f32>, %arg3: tensor<f32>):
    %6 = stablehlo.add %arg2, %arg3 : tensor<f32>
    stablehlo.return %6 : tensor<f32>
  }) {dimensions = array<i64: 0, 1>} : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>

  // Divide by batch size for 'batchmean' reduction
  %5 = stablehlo.divide %4, %cst : tensor<f32>

  return %5 : tensor<f32>
}

