module @smooth_l1_loss {
  func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
    // Step 1: Compute difference x = predictions - targets
    %diff = stablehlo.subtract %arg0, %arg1 : tensor<6x6xf32>

    // Step 2: Compute absolute value |x|
    %abs_diff = stablehlo.abs %diff : tensor<6x6xf32>

    // Step 3: Create constants
    %one = stablehlo.constant dense<1.0> : tensor<f32>
    %one_broadcasted = stablehlo.broadcast_in_dim %one, dims = [] : (tensor<f32>) -> tensor<6x6xf32>

    %half = stablehlo.constant dense<0.5> : tensor<f32>
    %half_broadcasted = stablehlo.broadcast_in_dim %half, dims = [] : (tensor<f32>) -> tensor<6x6xf32>

    // Step 4: Create condition |x| < 1.0
    %cond = "stablehlo.compare"(%abs_diff, %one_broadcasted) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

    // Step 5: Compute the two cases

    // Case 1: 0.5 * x^2 for |x| < 1
    %diff_squared = stablehlo.multiply %diff, %diff : tensor<6x6xf32>
    %case1 = stablehlo.multiply %half_broadcasted, %diff_squared : tensor<6x6xf32>

    // Case 2: |x| - 0.5 for |x| >= 1
    %case2 = stablehlo.subtract %abs_diff, %half_broadcasted : tensor<6x6xf32>

    // Step 6: Select based on condition
    %loss_per_element = "stablehlo.select"(%cond, %case1, %case2) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

    // Step 7: Reduce sum all elements
    %zero = stablehlo.constant dense<0.0> : tensor<f32>
    %sum_loss = "stablehlo.reduce"(%loss_per_element, %zero) ({
    ^bb0(%arg2: tensor<f32>, %arg3: tensor<f32>):
      %sum = stablehlo.add %arg2, %arg3 : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

    // Step 8: Divide by total number of elements (36)
    %total_elements = stablehlo.constant dense<36.0> : tensor<f32>
    %mean_loss = stablehlo.divide %sum_loss, %total_elements : tensor<f32>

    return %mean_loss : tensor<f32>
  }
}

func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
