  }) {dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

  %total_count = stablehlo.constant dense<36.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %total_count : tensor<f32>

  return %mean : tensor<f32>
}

