func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<16x6x7x7xf32>) -> tensor<16x7x1x1xf32> {
    // Transposed convolution
    // In PyTorch: nn.ConvTranspose2d(6, 7, 3, stride=2, padding=1, output_padding=1)
    // This means we're doing a transposed convolution which in StableHLO is just a regular convolution
    // with the right parameters

    // For transposed convolution in StableHLO, we use normal convolution but with:
    // - Flipped input/output spatial dimensions
    // - Adjusted padding and strides

    // But actually, let's think differently. A transposed convolution with:
    // - input: (N, C_in, H_in, W_in) = (16, 6, 7, 7)
    // - output: (N, C_out, H_out, W_out) = (16, 7, H_out, W_out)
    // - kernel: (C_in, C_out, kH, kW) = (6, 7, 3, 3)
    // - stride=2, padding=1, output_padding=1
    //
    // Output size calculation for transposed conv:
    // H_out = (H_in-1)*stride[0] - 2*padding[0] + dilation[0]*(kH-1) + output_padding[0] + 1
    // H_out = (7-1)*2 - 2*1 + 1*(3-1) + 1 + 1 = 6*2 - 2 + 2 + 1 + 1 = 14
    // So output should be (16, 7, 14, 14)

    // Actually, let me recheck the PyTorch convention:
    // PyTorch ConvTranspose2d weight shape is (in_channels, out_channels, kH, kW)
    // But StableHLO convolution expects (output_channels, input_channels, kH, kW) for the filter
    // So we need to transpose the weight appropriately

    // Let's reshape the weight from (6, 7, 3, 3) to (7, 6, 3, 3)
    %weight_transposed = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<6x7x3x3xf32>) -> tensor<7x6x3x3xf32>

    // Perform the convolution
    // Input: (16, 6, 7, 7)
    // Filter: (7, 6, 3, 3) 
    // With stride=2, padding=1, we get output of approximately (16, 7, 14, 14)
    %conv_result = "stablehlo.convolution"(%arg2, %weight_transposed) {
      window_strides = array<i64: 2, 2>,
      padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 1, 1>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<16x6x7x7xf32>, tensor<7x6x3x3xf32>) -> tensor<16x7x14x14xf32>

    // Add bias
    // Bias is of shape (7,) and needs to be broadcast to (16, 7, 14, 14)
    %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<16x7x14x14xf32>
    %with_bias = "stablehlo.add"(%conv_result, %bias_broadcast) : (tensor<16x7x14x14xf32>, tensor<16x7x14x14xf32>) -> tensor<16x7x14x14xf32>

    // Multiply by scalar 0.5
    %multiplier = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
    %multiplier_broadcast = "stablehlo.broadcast_in_dim"(%multiplier) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x7x14x14xf32>
    %multiplied = "stablehlo.multiply"(%with_bias, %multiplier_broadcast) : (tensor<16x7x14x14xf32>, tensor<16x7x14x14xf32>) -> tensor<16x7x14x14xf32>

    // First global average pooling over dimensions 2 and 3 (H and W)
    %zero_f32 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
    %pooled_once = "stablehlo.reduce"(%multiplied, %zero_f32) ({
    ^bb0(%arg3: tensor<f32>, %arg4: tensor<f32>):
      %sum = "stablehlo.add"(%arg3, %arg4) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
    }) {dimensions = array<i64: 2, 3>} : (tensor<16x7x14x14xf32>, tensor<f32>) -> tensor<16x7x1x1xf32>

    // Calculate the mean by dividing by the pooled dimensions (14*14 = 196)
    %divisor = "stablehlo.constant"() {value = dense<196.0> : tensor<f32>} : () -> tensor<f32>
    %divisor_broadcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x7x1x1xf32>
    %avg_pooled_once = "stablehlo.divide"(%pooled_once, %divisor_broadcast) : (tensor<16x7x1x1xf32>, tensor<16x7x1x1xf32>) -> tensor<16x7x1x1xf32>

    // Second global average pooling - but since we already have (16, 7, 1, 1), 
    // applying it again on dimensions 2,3 will just return the same tensor
    // However, let's apply it formally for completeness
    %pooled_twice = "stablehlo.reduce"(%avg_pooled_once, %zero_f32) ({
    ^bb0(%arg5: tensor<f32>, %arg6: tensor<f32>):
